<?php require_role('supervisor');$pageTitle='My Students';$pageSubtitle='Detailed supervision portfolio';$projects=db_all("SELECT p.*,u.full_name student_name,u.email,u.matric_no FROM projects p JOIN users u ON u.id=p.student_id WHERE p.supervisor_id=? ORDER BY u.full_name",[current_user()['id']]);include __DIR__.'/../includes/layout_top.php'; ?>
<div class="student-grid"><?php foreach($projects as $p):$progress=progress_for_project((int)$p['id']);$last=db_one("SELECT scheduled_at,status FROM sessions WHERE project_id=? ORDER BY scheduled_at DESC LIMIT 1",[$p['id']]);$pending=(int)(db_one("SELECT COUNT(*) c FROM milestones WHERE project_id=? AND status='submitted'",[$p['id']])['c']??0);?><article class="student-card"><div class="student-head"><div class="avatar"><?= e(strtoupper(substr($p['student_name'],0,1))) ?></div><div><h3><?= e($p['student_name']) ?></h3><p><?= e($p['matric_no']) ?> · <?= e($p['email']) ?></p></div></div><p><strong><?= e($p['title']) ?></strong></p><div class="meta-row"><span>Stage: <?= e($p['current_stage']) ?></span><span>Reviews: <?= $pending ?></span></div><div class="kpi-bar"><span>Approved progress</span><strong><?= $progress ?>%</strong></div><div class="progress-track"><div class="progress-bar" data-progress="<?= $progress ?>"></div></div><p class="hint">Latest session: <?= $last?e(format_date($last['scheduled_at'],'d M Y').' · '.$last['status']):'None recorded' ?></p><a class="button small secondary w-full" href="<?= e(url('index.php?page=supervisor-project&id='.(int)$p['id'])) ?>">Open project portfolio</a></article><?php endforeach; ?></div>
<?php include __DIR__.'/../includes/layout_bottom.php'; ?>
